BEGIN TRANSACTION;
CREATE TABLE addresses (
        AddressID INTEGER PRIMARY KEY AUTOINCREMENT,
        ParcelID TEXT,
        PropertyAddress TEXT,
        OwnerAddress TEXT,
        FOREIGN KEY (ParcelID) REFERENCES parcels(ParcelID)
    );
CREATE TABLE owners (
        OwnerID INTEGER PRIMARY KEY AUTOINCREMENT,
        OwnerName TEXT
    );
CREATE TABLE parcels (
        ParcelID TEXT PRIMARY KEY,
        LandUse TEXT,
        Acreage REAL,
        TaxDistrict TEXT
    );
GRRENBELT/RES',47.5,'GENERAL SERVICES DISTRICT');
GRRENBELT/RES',1.28,'GENERAL SERVICES DISTRICT');
GRRENBELT/RES',5.33,'GENERAL SERVICES DISTRICT');
CREATE TABLE properties (
        PropertyID INTEGER PRIMARY KEY AUTOINCREMENT,
        ParcelID TEXT,
        LandValue REAL,
        BuildingValue REAL,
        TotalValue REAL,
        YearBuilt INTEGER,
        Bedrooms INTEGER,
        FullBath INTEGER,
        HalfBath INTEGER,
        FOREIGN KEY (ParcelID) REFERENCES parcels(ParcelID)
    );
CREATE TABLE sales (
        SaleID INTEGER PRIMARY KEY AUTOINCREMENT,
        ParcelID TEXT,
        OwnerID INTEGER,
        SaleDate TEXT,
        SalePrice REAL,
        SoldAsVacant TEXT,
        LegalReference TEXT,
        FOREIGN KEY (ParcelID) REFERENCES parcels(ParcelID),
        FOREIGN KEY (OwnerID) REFERENCES owners(OwnerID)
    );
DELETE FROM "sqlite_sequence";
COMMIT;
